package ae.ot;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/** Central OT server: a document plus the log of every accepted (transformed) operation. */
public final class Server {

    /** An accepted operation, as broadcast to all clients. */
    public record Accepted(int revision, String clientId, TextOp op) {}

    private final String initial;
    private final List<Accepted> log = new ArrayList<>();
    private String doc;

    public Server(String initial) {
        this.initial = Objects.requireNonNull(initial);
        this.doc = initial;
    }

    public String document() { return doc; }

    public int revision() { return log.size(); }

    /**
     * Accepts {@code op}, made by {@code clientId} against revision {@code baseRev}.
     * The op is transformed over log entries {@code baseRev..} (history is the first
     * argument, so it wins insert ties). Failures leave the server unchanged.
     */
    public Accepted receive(String clientId, int baseRev, TextOp op) {
        Objects.requireNonNull(clientId);
        Objects.requireNonNull(op);
        if (baseRev < 0 || baseRev > log.size()) {
            throw new IllegalArgumentException("bad base revision " + baseRev + " (server at " + log.size() + ")");
        }
        TextOp cur = op;
        for (int i = baseRev; i < log.size(); i++) {
            if (cur.baseLength() != log.get(i).op().baseLength()) {
                throw new IllegalArgumentException("op base length " + cur.baseLength()
                        + " does not match revision " + baseRev + " document");
            }
            cur = TextOp.transform(log.get(i).op(), cur).second();
        }
        if (cur.baseLength() != doc.length()) {
            throw new IllegalArgumentException("op base length " + cur.baseLength()
                    + " does not match document length " + doc.length());
        }
        String next = cur.apply(doc);
        doc = next;
        Accepted acc = new Accepted(log.size() + 1, clientId, cur);
        log.add(acc);
        return acc;
    }

    /** Re-applies the whole log to the initial text. */
    public String replayLog() {
        String d = initial;
        for (Accepted a : log) d = a.op().apply(d);
        return d;
    }
}

package ae.ot;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * An immutable text operation: a sequence of retain / insert / delete components
 * measured in UTF-16 chars. Instances are always normalised (see {@link Builder}).
 */
public final class TextOp {

    /** One component of an operation. */
    public sealed interface Comp permits Retain, Insert, Delete {}

    /** Keep {@code n} chars. */
    public record Retain(int n) implements Comp {}

    /** Insert {@code text}. */
    public record Insert(String text) implements Comp {}

    /** Delete {@code n} chars. */
    public record Delete(int n) implements Comp {}

    /** Result of {@link #transform}. */
    public record Pair(TextOp first, TextOp second) {}

    private final List<Comp> comps;
    private final int baseLength;
    private final int targetLength;

    private TextOp(List<Comp> comps) {
        this.comps = List.copyOf(comps);
        int b = 0;
        int t = 0;
        for (Comp c : comps) {
            switch (c) {
                case Retain r -> { b += r.n(); t += r.n(); }
                case Insert i -> t += i.text().length();
                case Delete d -> b += d.n();
            }
        }
        baseLength = b;
        targetLength = t;
    }

    /** Builds a normalised operation. */
    public static final class Builder {
        private final List<Comp> list = new ArrayList<>();

        public Builder retain(int n) {
            if (n < 0) throw new IllegalArgumentException("negative retain");
            if (n == 0) return this;
            int last = list.size() - 1;
            if (last >= 0 && list.get(last) instanceof Retain r) list.set(last, new Retain(r.n() + n));
            else list.add(new Retain(n));
            return this;
        }

        public Builder delete(int n) {
            if (n < 0) throw new IllegalArgumentException("negative delete");
            if (n == 0) return this;
            int last = list.size() - 1;
            if (last >= 0 && list.get(last) instanceof Delete d) list.set(last, new Delete(d.n() + n));
            else list.add(new Delete(n));
            return this;
        }

        public Builder insert(String s) {
            Objects.requireNonNull(s, "text");
            if (s.isEmpty()) return this;
            int last = list.size() - 1;
            if (last >= 0 && list.get(last) instanceof Delete) {
                // canonical order: insert before an adjacent delete
                if (last >= 1 && list.get(last - 1) instanceof Insert i) list.set(last - 1, new Insert(i.text() + s));
                else list.add(last, new Insert(s));
            } else if (last >= 0 && list.get(last) instanceof Insert i) {
                list.set(last, new Insert(i.text() + s));
            } else {
                list.add(new Insert(s));
            }
            return this;
        }

        public TextOp build() {
            return new TextOp(list);
        }
    }

    public List<Comp> components() { return comps; }

    public int baseLength() { return baseLength; }

    public int targetLength() { return targetLength; }

    /** Applies this op to {@code doc}; the doc length must equal {@link #baseLength()}. */
    public String apply(String doc) {
        if (doc.length() != baseLength) {
            throw new IllegalArgumentException("base length " + baseLength + " != document length " + doc.length());
        }
        StringBuilder sb = new StringBuilder(targetLength);
        int pos = 0;
        for (Comp c : comps) {
            switch (c) {
                case Retain r -> { sb.append(doc, pos, pos + r.n()); pos += r.n(); }
                case Insert i -> sb.append(i.text());
                case Delete d -> pos += d.n();
            }
        }
        return sb.toString();
    }

    /** The op that undoes this one when applied to the result of {@code apply(doc)}. */
    public TextOp invert(String doc) {
        if (doc.length() != baseLength) {
            throw new IllegalArgumentException("base length " + baseLength + " != document length " + doc.length());
        }
        Builder b = new Builder();
        int pos = 0;
        for (Comp c : comps) {
            switch (c) {
                case Retain r -> { b.retain(r.n()); pos += r.n(); }
                case Insert i -> b.delete(i.text().length());
                case Delete d -> { b.insert(doc.substring(pos, pos + d.n())); pos += d.n(); }
            }
        }
        return b.build();
    }

    /** Cursor over components allowing partial consumption. */
    private static final class Cur {
        private final List<Comp> l;
        private int i;
        private int off;

        Cur(TextOp op) { l = op.comps; }

        Comp peek() { return i < l.size() ? l.get(i) : null; }

        int rem() {
            return switch (l.get(i)) {
                case Retain r -> r.n() - off;
                case Insert s -> s.text().length() - off;
                case Delete d -> d.n() - off;
            };
        }

        String text(int n) { return ((Insert) l.get(i)).text().substring(off, off + n); }

        void skip(int n) {
            if (n == rem()) { i++; off = 0; } else { off += n; }
        }
    }

    /** Composition: applying the result equals applying {@code a} then {@code b}. */
    public static TextOp compose(TextOp a, TextOp b) {
        if (a.targetLength != b.baseLength) {
            throw new IllegalArgumentException("compose length mismatch: " + a.targetLength + " vs " + b.baseLength);
        }
        Builder out = new Builder();
        Cur x = new Cur(a);
        Cur y = new Cur(b);
        while (x.peek() != null || y.peek() != null) {
            if (x.peek() instanceof Delete) {
                int n = x.rem();
                out.delete(n);
                x.skip(n);
            } else if (y.peek() instanceof Insert) {
                int n = y.rem();
                out.insert(y.text(n));
                y.skip(n);
            } else {
                int n = Math.min(x.rem(), y.rem());
                Comp ca = x.peek();
                Comp cb = y.peek();
                if (ca instanceof Retain && cb instanceof Retain) out.retain(n);
                else if (ca instanceof Retain) out.delete(n);
                else if (cb instanceof Retain) out.insert(x.text(n));
                // insert then delete cancels
                x.skip(n);
                y.skip(n);
            }
        }
        return out.build();
    }

    /**
     * Transforms two concurrent ops with the same base. Returns {@code (a', b')} such that
     * {@code b'.apply(a.apply(d)) == a'.apply(b.apply(d))}. When both insert at the same
     * position, {@code a}'s text comes first.
     */
    public static Pair transform(TextOp a, TextOp b) {
        if (a.baseLength != b.baseLength) {
            throw new IllegalArgumentException("transform base mismatch: " + a.baseLength + " vs " + b.baseLength);
        }
        Builder ap = new Builder();
        Builder bp = new Builder();
        Cur x = new Cur(a);
        Cur y = new Cur(b);
        while (x.peek() != null || y.peek() != null) {
            if (x.peek() instanceof Insert) {
                int n = x.rem();
                ap.insert(x.text(n));
                bp.retain(n);
                x.skip(n);
            } else if (y.peek() instanceof Insert) {
                int n = y.rem();
                bp.insert(y.text(n));
                ap.retain(n);
                y.skip(n);
            } else {
                int n = Math.min(x.rem(), y.rem());
                Comp ca = x.peek();
                Comp cb = y.peek();
                if (ca instanceof Retain && cb instanceof Retain) { ap.retain(n); bp.retain(n); }
                else if (ca instanceof Delete && cb instanceof Retain) ap.delete(n);
                else if (ca instanceof Retain && cb instanceof Delete) bp.delete(n);
                // both delete: already gone on the other side
                x.skip(n);
                y.skip(n);
            }
        }
        return new Pair(ap.build(), bp.build());
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof TextOp t && comps.equals(t.comps);
    }

    @Override
    public int hashCode() { return comps.hashCode(); }

    @Override
    public String toString() {
        List<String> parts = new ArrayList<>();
        for (Comp c : comps) {
            switch (c) {
                case Retain r -> parts.add("R" + r.n());
                case Insert i -> parts.add("I\"" + i.text() + "\"");
                case Delete d -> parts.add("D" + d.n());
            }
        }
        return "[" + String.join(", ", parts) + "]";
    }
}

package ae.ot;

import java.util.Objects;
import java.util.Optional;

/** OT client: Synchronized / AwaitingAck(out) / AwaitingAckWithBuffer(out, buf). */
public final class Client {

    /** The three protocol states. */
    public enum State { SYNCHRONIZED, AWAITING_ACK, AWAITING_ACK_WITH_BUFFER }

    /** An operation to send to the server, based on revision {@code baseRevision}. */
    public record Send(int baseRevision, TextOp op) {}

    private final String id;
    private String doc;
    private int revision;
    private TextOp out;
    private TextOp buf;

    public Client(String id, String initial) {
        this.id = Objects.requireNonNull(id);
        this.doc = Objects.requireNonNull(initial);
    }

    public String id() { return id; }

    public String document() { return doc; }

    public int revision() { return revision; }

    public State state() {
        if (out == null) return State.SYNCHRONIZED;
        return buf == null ? State.AWAITING_ACK : State.AWAITING_ACK_WITH_BUFFER;
    }

    /** Applies a local edit; returns what must be sent now, if anything. */
    public Optional<Send> local(TextOp op) {
        String next = op.apply(doc); // validates before any mutation
        TextOp newBuf = buf == null ? null : TextOp.compose(buf, op);
        doc = next;
        if (out == null) {
            out = op;
            return Optional.of(new Send(revision, op));
        }
        if (buf == null) buf = op;
        else buf = newBuf;
        return Optional.empty();
    }

    /** Applies an operation broadcast by the server (from another client). */
    public void remote(TextOp serverOp) {
        TextOp op = serverOp;
        TextOp newOut = out;
        TextOp newBuf = buf;
        if (out != null) {
            TextOp.Pair p = TextOp.transform(op, out);
            op = p.first();
            newOut = p.second();
            if (buf != null) {
                TextOp.Pair q = TextOp.transform(op, buf);
                op = q.first();
                newBuf = q.second();
            }
        }
        String next = op.apply(doc); // validate before mutating
        doc = next;
        out = newOut;
        buf = newBuf;
        revision++;
    }

    /** The server accepted our outstanding op; returns the buffered op to send next, if any. */
    public Optional<Send> ack() {
        if (out == null) throw new IllegalStateException("unexpected ack in state SYNCHRONIZED");
        revision++;
        if (buf == null) {
            out = null;
            return Optional.empty();
        }
        out = buf;
        buf = null;
        return Optional.of(new Send(revision, out));
    }
}

package ae.ot;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Seeded in-process simulation: clients and a server joined by per-client FIFO channels.
 * The scheduler picks, uniformly at random, which pending delivery (or local edit) runs next.
 */
public final class Simulation {

    private record Down(Server.Accepted acc, boolean ack) {}

    private final Random rnd;
    private final Server server;
    private final List<Client> clients = new ArrayList<>();
    private final List<ArrayDeque<Client.Send>> up = new ArrayList<>();
    private final List<ArrayDeque<Down>> down = new ArrayList<>();
    private int maxInFlight;

    public Simulation(long seed, String initial, int clientCount) {
        if (clientCount < 1) throw new IllegalArgumentException("need at least one client");
        rnd = new Random(seed);
        server = new Server(initial);
        for (int i = 0; i < clientCount; i++) {
            clients.add(new Client("c" + i, initial));
            up.add(new ArrayDeque<>());
            down.add(new ArrayDeque<>());
        }
    }

    public Server server() { return server; }

    public Client client(int i) { return clients.get(i); }

    /** Largest number of clients that had an unacknowledged edit at the same time. */
    public int maxInFlight() { return maxInFlight; }

    /** Applies {@code op} as a local edit of client {@code i}. */
    public void edit(int i, TextOp op) {
        client(i).local(op).ifPresent(up.get(i)::add);
        track();
    }

    private void track() {
        int n = 0;
        for (Client c : clients) if (c.state() != Client.State.SYNCHRONIZED) n++;
        maxInFlight = Math.max(maxInFlight, n);
    }

    /** Runs {@code edits} random local edits interleaved with random deliveries, then drains. */
    public void runRandom(int edits) {
        int left = edits;
        while (left > 0 || pending() > 0) {
            int p = pending();
            if (left > 0 && (p == 0 || rnd.nextInt(3) == 0)) {
                int i = rnd.nextInt(clients.size());
                edit(i, randomOp(client(i).document()));
                left--;
            } else {
                deliverRandom();
            }
        }
    }

    /** Delivers every pending message in random order. */
    public void runToQuiescence() {
        while (pending() > 0) deliverRandom();
    }

    private int pending() {
        int n = 0;
        for (int i = 0; i < clients.size(); i++) n += up.get(i).size() + down.get(i).size();
        return n;
    }

    private void deliverRandom() {
        int pick = rnd.nextInt(pending());
        for (int i = 0; i < clients.size(); i++) {
            if (pick < up.get(i).size()) { deliverUp(i); return; }
            pick -= up.get(i).size();
            if (pick < down.get(i).size()) { deliverDown(i); return; }
            pick -= down.get(i).size();
        }
        throw new IllegalStateException("scheduler fell through");
    }

    // FIFO per channel: always deliver the head of the chosen client's channel.
    private void deliverUp(int i) {
        Client.Send s = up.get(i).poll();
        Server.Accepted acc = server.receive(client(i).id(), s.baseRevision(), s.op());
        for (int j = 0; j < clients.size(); j++) down.get(j).add(new Down(acc, j == i));
    }

    private void deliverDown(int i) {
        Down d = down.get(i).poll();
        if (d.ack()) client(i).ack().ifPresent(up.get(i)::add);
        else client(i).remote(d.acc().op());
        track();
    }

    private TextOp randomOp(String doc) {
        TextOp.Builder b = new TextOp.Builder();
        int i = 0;
        while (i < doc.length()) {
            int n = Math.min(1 + rnd.nextInt(4), doc.length() - i);
            int k = rnd.nextInt(doc.length() > 30 ? 3 : 5);
            if (k < 2) { b.retain(n); i += n; }
            else if (k == 2) { b.delete(n); i += n; }
            else { b.insert(text()); }
        }
        if (rnd.nextInt(2) == 0 || doc.isEmpty()) b.insert(text());
        return b.build();
    }

    private String text() {
        int n = 1 + rnd.nextInt(3);
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < n; k++) sb.append((char) ('a' + rnd.nextInt(26)));
        return sb.toString();
    }

    /** True when nothing is pending and every client holds the server's document. */
    public boolean converged() {
        if (pending() > 0) return false;
        for (Client c : clients) if (!c.document().equals(server.document())) return false;
        return true;
    }

    /** Test hook: replaces client {@code i} by a fresh client holding {@code text}. */
    public void corruptClientForTest(int i, String text) {
        clients.set(i, new Client(client(i).id(), text));
    }

    public String report() {
        StringBuilder sb = new StringBuilder("server rev " + server.revision() + ": \"" + server.document() + "\"\n");
        for (Client c : clients) {
            sb.append(c.id()).append(' ').append(c.state()).append(" rev ").append(c.revision())
              .append(": \"").append(c.document()).append("\"\n");
        }
        return sb.toString();
    }
}

